{"implementation":"def solve(case):
    threshold = case["threshold"]
    calls = case["calls"]
    retained = []
    for call in calls:
        if not call["parseable"]:
            continue
        benefit = call["loss_without_call"] - call["loss_with_call"]
        score = benefit / call["prediction_tokens"]
        if score >= threshold:
            retained.append(call["call_id"])
    return retained"}
